using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;namespace AshkanJobCenter.UI{public static class Ui{public static Button Button(string text,bool primary=true){var b=new Button{Text=text,Height=38,AutoSize=true,FlatStyle=FlatStyle.Flat,BackColor=primary?Theme.Primary:Theme.Surface,ForeColor=primary?Color.White:Theme.Text,Cursor=Cursors.Hand,Padding=new Padding(12,0,12,0)};b.FlatAppearance.BorderColor=primary?Theme.Primary:Theme.Border;return b;}public static Label Label(string text,float size=10,bool bold=false){return new Label{Text=text,AutoSize=true,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=Theme.Text};}public static TextBox Text(string placeholder=""){return new TextBox{Height=34,Font=Theme.Font,BorderStyle=BorderStyle.FixedSingle,Tag=placeholder};}public static DataGridView Grid(){var g=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Theme.Surface,BorderStyle=BorderStyle.None,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,RowHeadersVisible=false};g.EnableHeadersVisualStyles=false;g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(235,241,247);g.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Text;g.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",10,FontStyle.Bold);g.ColumnHeadersHeight=40;g.RowTemplate.Height=36;g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(221,236,249);g.DefaultCellStyle.SelectionForeColor=Theme.Text;return g;}public static Panel Card(){return new Panel{BackColor=Theme.Surface,Padding=new Padding(18),Margin=new Padding(8)};}}}